mapper.select:
select gp.shop_code, gp.goodscode, gp.partnercode, coalesce(nullif(trim(p.partnername), ''), gp.partnername) as partnername, gp.inboundtimes, gp.lastdoccode, gp.lastdocdate, gp.lastcostprice, p.activeflag from sdsshop.u_m_goods_partner gp left join sdsshop.u_m_partner p on p.shop_code = gp.shop_code and p.partnercode = gp.partnercode where gp.shop_code = #{shopCode} and gp.goodscode in
#{code}
order by gp.goodscode, gp.lastdocdate desc, gp.inboundtimes desc, gp.partnercode
